package com.ncdex.instrument.document;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import jakarta.validation.constraints.*;
@Document("instruments") public class Instrument { @Id private String id; @NotBlank @Indexed(unique=true) private String symbol; @NotBlank private String name; @NotBlank private String category; @Positive private double indicativePrice; private boolean active=true; private long orderActivityCount=0; public Instrument(){} public String getId(){return id;} public void setId(String v){id=v;} public String getSymbol(){return symbol;} public void setSymbol(String v){symbol=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public double getIndicativePrice(){return indicativePrice;} public void setIndicativePrice(double v){indicativePrice=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public long getOrderActivityCount(){return orderActivityCount;} public void setOrderActivityCount(long v){orderActivityCount=v;} }
